import{_ as i,A as p,o,c as d,O as r,b as s,w as n,Z as g,E as l,a}from"./chunks/framework.2c2d5a61.js";const N=JSON.parse('{"title":"Netty","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/17-Netty.md","filePath":"interview/后端/Java/17-Netty.md","lastUpdated":1793001193000}'),h={name:"interview/后端/Java/17-Netty.md"};function u(c,t,y,E,B,b){const e=p("Mermaid");return o(),d("div",null,[t[2]||(t[2]=r('<h1 id="netty" tabindex="-1">Netty <a class="header-anchor" href="#netty" aria-label="Permalink to &quot;Netty&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点按「定义 → 原理 → 要点 / 易错点」组织，只讲知识点</li></ul></blockquote><hr><h2 id="_1-netty-是什么、其设计哲学-★★★" tabindex="-1">1. Netty 是什么、其设计哲学 ★★★ <a class="header-anchor" href="#_1-netty-是什么、其设计哲学-★★★" aria-label="Permalink to &quot;1. Netty 是什么、其设计哲学 ★★★&quot;">​</a></h2><p><strong>Netty</strong> 是一个基于 Java NIO 的<strong>异步事件驱动</strong>的高性能网络应用框架，用来快速开发高性能、高可靠的网络服务端和客户端。</p><ul><li>它把 NIO 里难用又容易出错的底层细节（<strong>Selector</strong>、<strong>ByteBuffer</strong>、<strong>Channel</strong>）全部封装掉，对外只暴露统一的 API。</li><li>核心抽象是「<strong>Channel + Pipeline + Handler</strong>」这套<strong>组件化模型</strong>：连接由 Channel 表示，处理逻辑挂在 Pipeline 的 Handler 链上，网络编程可以像搭积木一样组合。</li><li>运行机制是<strong>非阻塞 IO + Reactor 线程模型</strong>，把<strong>连接管理</strong>和<strong>业务处理</strong>解耦。</li><li>设计哲学：<strong>异步非阻塞</strong>、<strong>事件驱动</strong>、<strong>组件可插拔</strong>（Pipeline、Handler、Codec 都能自定义替换）、追求高性能（<strong>零拷贝</strong>、<strong>内存池</strong>、<strong>无锁化串行设计</strong>）。</li><li>最对口的场景是<strong>高并发长连接</strong>：设备接入层几千个长连接，只靠少量 <strong>worker 线程</strong>就能撑住。</li></ul><hr><h2 id="_2-netty-相比传统-java-网络编程-bio-nio-的优势-★★★" tabindex="-1">2. Netty 相比传统 Java 网络编程（BIO/NIO）的优势 ★★★ <a class="header-anchor" href="#_2-netty-相比传统-java-网络编程-bio-nio-的优势-★★★" aria-label="Permalink to &quot;2. Netty 相比传统 Java 网络编程（BIO/NIO）的优势 ★★★&quot;">​</a></h2><p>三种 IO 模型的差别：</p><ul><li><strong>BIO</strong>：<strong>同步阻塞</strong>，一个连接一个线程，线程阻塞在 <code>read</code> 上等数据。连接一多<strong>线程数爆炸</strong>，CPU 大量时间耗在<strong>线程切换</strong>上，还要为每个线程付出<strong>线程栈内存</strong>。</li><li><strong>NIO</strong>：<strong>同步非阻塞</strong>，用 <strong>Selector 多路复用</strong>，一个线程管多个连接。但原生 API 太底层、难用：ByteBuffer 读写要 <code>flip</code> 切换模式、<strong>粘包半包要自己处理</strong>，还有 <strong>epoll 空轮询 bug</strong>（Selector 空转导致 CPU 被打满），代码又臭又长。</li><li><strong>AIO</strong>：异步非阻塞，但生态不成熟、实际用得少。</li></ul><p>Netty 把这些坑都填了，还额外做了性能优化：</p><ul><li>提供统一的异步事件驱动 API，屏蔽底层细节；</li><li>自带编解码器、<strong>粘包拆包</strong>处理器、<strong>空闲检测</strong>等开箱即用的 Handler，不用自己造轮子；</li><li>额外的性能优化：<strong>零拷贝</strong>、<strong>内存池</strong>、<strong>Reactor 线程模型</strong>。</li></ul><p>一句话：<strong>BIO 连接多了扛不住，NIO 太底层难写，Netty 是 NIO 的高层封装加优化</strong>。</p><hr><h2 id="_3-netty-的-reactor-模型及单线程-多线程-主从多线程三种模式-★★★" tabindex="-1">3. Netty 的 Reactor 模型及单线程/多线程/主从多线程三种模式 ★★★ <a class="header-anchor" href="#_3-netty-的-reactor-模型及单线程-多线程-主从多线程三种模式-★★★" aria-label="Permalink to &quot;3. Netty 的 Reactor 模型及单线程/多线程/主从多线程三种模式 ★★★&quot;">​</a></h2><p><strong>Reactor</strong> 是一种基于 <strong>IO 多路复用</strong>的<strong>事件分发模型</strong>：一个（或一组）线程负责监听所有连接的 IO 事件，事件到达后就分发给对应的 handler 处理。</p><p>三种模式：</p><ul><li><strong>单 Reactor 单线程</strong>：一个线程既 accept 连接，又读写数据，还处理业务。全程<strong>串行</strong>，一个 handler 处理慢就卡住所有连接，只适合小并发场景。</li><li><strong>单 Reactor 多线程</strong>：一个 Reactor 线程只负责 accept 和事件分发，业务处理丢进<strong>线程池</strong>，IO 线程不再被业务逻辑阻塞。</li><li><strong>主从 Reactor 多线程</strong>：main Reactor（<strong>bossGroup</strong>）只负责 accept，多个 sub Reactor（<strong>workerGroup</strong>）各自分管一部分连接的读写，业务再交给线程池。<strong>Netty 默认就是这种模型</strong>，也是生产环境最常用的。</li></ul>',18)),(o(),s(g,null,{default:n(()=>[l(e,{id:"mermaid-133",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5Bmain%20Reactor%3Cbr%2F%3EbossGroup%5D%20--%3E%7Caccept%20%E8%BF%9E%E6%8E%A5%7C%20B%5Bsub%20Reactor%3Cbr%2F%3EworkerGroup%5D%0A%20%20%20%20B%20--%3E%7C%E5%88%86%E9%85%8D%E8%BF%9E%E6%8E%A5%E8%AF%BB%E5%86%99%7C%20C%5BThreadPool%3Cbr%2F%3E%E4%B8%9A%E5%8A%A1%E5%A4%84%E7%90%86%5D%0A"})]),fallback:n(()=>t[0]||(t[0]=[a(" Loading... ")])),_:1})),t[3]||(t[3]=r('<p>这种拆分的价值在于两层解耦：把「<strong>建连</strong>」和「<strong>读写</strong>」拆开，再把「读写」和「<strong>业务处理</strong>」拆开，单个报文解析慢不会拖住其他连接。</p><hr><h2 id="_4-netty-的核心组件有哪些-channel、eventloop、channelpipeline、channelhandler、bytebuf、bootstrap-★★★" tabindex="-1">4. Netty 的核心组件有哪些（Channel、EventLoop、ChannelPipeline、ChannelHandler、ByteBuf、Bootstrap）★★★ <a class="header-anchor" href="#_4-netty-的核心组件有哪些-channel、eventloop、channelpipeline、channelhandler、bytebuf、bootstrap-★★★" aria-label="Permalink to &quot;4. Netty 的核心组件有哪些（Channel、EventLoop、ChannelPipeline、ChannelHandler、ByteBuf、Bootstrap）★★★&quot;">​</a></h2><p>六个核心组件：</p><ul><li><strong>Channel</strong>：对 Socket 的抽象，代表一条连接，所有读写都通过它。</li><li><strong>EventLoop / EventLoopGroup</strong>：事件循环线程。一个 EventLoop 绑定一个线程，管理一组 Channel 的全部 IO 事件和任务；EventLoopGroup 是 EventLoop 的集合，也就是线程组。</li><li><strong>ChannelPipeline</strong>：<strong>责任链</strong>，链上挂着一串 ChannelHandler，数据按顺序流过。</li><li><strong>ChannelHandler</strong>：处理器，分**入站（Inbound）<strong>和</strong>出站（Outbound）**两类，负责编解码和业务处理。</li><li><strong>ByteBuf</strong>：Netty 的字节容器，比原生 ByteBuffer 好用——<strong>读写指针分离</strong>（不用 flip）、支持<strong>池化</strong>、支持<strong>引用计数</strong>。</li><li><strong>Bootstrap / ServerBootstrap</strong>：启动引导类，配置线程组、Channel 类型、Pipeline 等参数后，拉起客户端或服务端。</li></ul><p>组件之间的关系是理解 Netty 的<strong>骨架</strong>：Bootstrap 创建 Channel → Channel 注册并绑定到一个 EventLoop → 数据在 Pipeline 的 Handler 链上流转 → Handler 内用 ByteBuf 读写数据。</p><hr><h2 id="_5-channelpipeline-的作用、入站出站-handler-执行顺序-★★★" tabindex="-1">5. ChannelPipeline 的作用、入站出站 handler 执行顺序 ★★★ <a class="header-anchor" href="#_5-channelpipeline-的作用、入站出站-handler-执行顺序-★★★" aria-label="Permalink to &quot;5. ChannelPipeline 的作用、入站出站 handler 执行顺序 ★★★&quot;">​</a></h2><p><strong>ChannelPipeline</strong> 是一条双向链表结构的<strong>责任链</strong>。</p><ul><li><strong>入站事件</strong>（读数据）：从链头往链尾依次触发 <strong>InboundHandler</strong>。</li><li><strong>出站事件</strong>（写数据）：从链尾往链头依次触发 <strong>OutboundHandler</strong>，方向与入站相反。</li></ul><p>典型顺序：入站先<strong>粘包解码</strong>、再<strong>协议解码</strong>、最后业务处理；出站先<strong>协议编码</strong>、再<strong>帧编码</strong>。顺序一旦搞反，粘包就会处理错、报文解析就会乱。</p><p>写数据有两个容易混淆的入口：</p><ul><li><strong>ChannelHandlerContext.write</strong>：从当前 handler 所在位置开始，往前（向链头方向）找 OutboundHandler，只有它之前的出站 handler 会执行。</li><li><strong>Channel.write</strong>：从链尾开始，走完整条 outbound 链。</li></ul><p>两者<strong>起点不同</strong>，用错就会出现数据没走完整条编码链、报文格式不对的问题。</p>',14)),(o(),s(g,null,{default:n(()=>[l(e,{id:"mermaid-219",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%85%A5%E7%AB%99%E6%95%B0%E6%8D%AE%5D%20--%3E%20B%5BInbound%20%E8%A7%A3%E7%A0%81%E5%99%A8%3Cbr%2F%3E%E7%B2%98%E5%8C%85%C2%B7%E5%8D%8F%E8%AE%AE%5D%0A%20%20%20%20B%20--%3E%20C%5BInbound%20%E4%B8%9A%E5%8A%A1%20handler%5D%0A%20%20%20%20C%20--%3E%20D%5BOutbound%20%E7%BC%96%E7%A0%81%E5%99%A8%3Cbr%2F%3E%E5%8D%8F%E8%AE%AE%C2%B7%E5%B8%A7%5D%0A%20%20%20%20D%20--%3E%20E%5B%E5%87%BA%E7%AB%99%E6%95%B0%E6%8D%AE%5D%0A"})]),fallback:n(()=>t[1]||(t[1]=[a(" Loading... ")])),_:1})),t[4]||(t[4]=r('<hr><h2 id="_6-netty-中如何解决-tcp-粘包-拆包-★★★" tabindex="-1">6. Netty 中如何解决 TCP 粘包/拆包 ★★★ <a class="header-anchor" href="#_6-netty-中如何解决-tcp-粘包-拆包-★★★" aria-label="Permalink to &quot;6. Netty 中如何解决 TCP 粘包/拆包 ★★★&quot;">​</a></h2><p><strong>TCP 是字节流，没有消息边界</strong>，所以会出现<strong>粘包</strong>（多个小包粘在一起）和<strong>拆包</strong>（一个大包被拆成多段）。</p><p>原因有三类：发送方的发送缓冲会合并小包、接收方读取不及时、<strong>MSS/MTU 限制</strong>导致大包被分片。</p><p>解决思路就三条，核心都是「在字节流里人为划出帧边界」：</p><ul><li><strong>定长消息</strong>：每条消息固定长度，不够补齐。</li><li><strong>分隔符</strong>：用特殊字符标记消息结束，但消息内容不能包含该字符。</li><li><strong>消息头带长度字段</strong>：先读长度，再按长度读满整个包，最通用。</li></ul><p>Netty 内置了对应解码器，<strong>开箱即用</strong>：</p><ul><li><strong>FixedLengthFrameDecoder</strong>：定长。</li><li><strong>DelimiterBasedFrameDecoder</strong>：分隔符。</li><li><strong>LengthFieldBasedFrameDecoder</strong>：长度字段，最常用。</li></ul><p>注意：如果直接继承 <strong>ByteToMessageDecoder</strong> 而不做粘包处理，会出现一个 buffer 里塞了多个帧、或者<strong>半包解析错乱</strong>的问题。接自定义协议第一步就是把<strong>帧边界</strong>定清楚。</p><hr><h2 id="_7-netty-高性能表现在哪些方面-★★★" tabindex="-1">7. Netty 高性能表现在哪些方面 ★★★ <a class="header-anchor" href="#_7-netty-高性能表现在哪些方面-★★★" aria-label="Permalink to &quot;7. Netty 高性能表现在哪些方面 ★★★&quot;">​</a></h2><p>高性能来自几个层面的叠加：</p><ul><li><strong>Reactor 线程模型</strong>：少量线程撑起大量连接，减少线程创建与切换开销。<strong>worker 线程数远小于连接数</strong>，这就是多路复用的直接收益。</li><li><strong>零拷贝</strong>：减少数据在<strong>内核态和用户态</strong>之间的搬运。</li><li><strong>内存池</strong>：ByteBuf 池化复用，减少对象创建和 <strong>GC 压力</strong>；配合<strong>池化分配器</strong>还能控制<strong>直接内存</strong>占用，避免频繁创建导致 <strong>GC 抖动</strong>。</li><li><strong>无锁化串行设计</strong>：同一 Channel 的 IO 事件和任务都在同一个 EventLoop 线程执行，天然不用加锁，避免锁竞争。</li><li><strong>高效数据结构</strong>：<strong>FastThreadLocal</strong>、<strong>MPSC</strong>（多生产者单消费者）队列等。</li></ul><p>这几项叠加起来就是<strong>高吞吐、低延迟</strong>。</p><hr><h2 id="_8-netty-的零拷贝技术如何实现-★★★" tabindex="-1">8. Netty 的零拷贝技术如何实现 ★★★ <a class="header-anchor" href="#_8-netty-的零拷贝技术如何实现-★★★" aria-label="Permalink to &quot;8. Netty 的零拷贝技术如何实现 ★★★&quot;">​</a></h2><p>Netty 的<strong>零拷贝</strong>不是字面上「完全不拷贝」，而是「减少不必要的拷贝」，可以从几个层面实现：</p><ul><li><strong>直接内存（堆外 ByteBuf）</strong>：用堆外缓冲收发数据，省掉堆内与堆外之间的一次拷贝；默认用 <strong>PooledByteBufAllocator</strong> 池化分配。</li><li><strong>CompositeByteBuf</strong>：把多个 ByteBuf 组合成一个<strong>逻辑视图</strong>，不实际合并拷贝。</li><li><strong>FileRegion 的 transferTo</strong>：底层用操作系统 <strong>sendfile</strong>，文件数据从内核态直接发到 socket，不经过用户态。</li><li><strong>slice / wrap</strong>：对已有缓冲做切片和包装，都是视图操作，不复制数据。</li></ul><p>核心是<strong>减少不必要的内存拷贝，而不是完全不拷贝</strong>。代价是堆外内存不在 <strong>GC 管辖范围</strong>，必须严格按<strong>引用计数 release</strong> 手动管理，否则会<strong>内存泄漏</strong>甚至<strong>直接内存 OOM</strong>。可用 <code>io.netty.leakDetection.level</code> 开启泄漏检测辅助排查。</p><hr><h2 id="_9-netty-的线程模型如何设计-★★★" tabindex="-1">9. Netty 的线程模型如何设计 ★★★ <a class="header-anchor" href="#_9-netty-的线程模型如何设计-★★★" aria-label="Permalink to &quot;9. Netty 的线程模型如何设计 ★★★&quot;">​</a></h2><p>Netty 线程模型的核心是 <strong>EventLoop 体系</strong>：</p><ul><li><strong>NioEventLoopGroup</strong> 是一组 EventLoop，每个 EventLoop 是一个<strong>单线程执行器</strong>，<strong>绑定一个线程</strong>。</li><li><strong>boss 线程组</strong>只负责 accept 连接，<strong>worker 线程组</strong>负责连接读写，这就是<strong>主从 Reactor</strong> 的落地形式。</li><li>一个 EventLoop 会被分配多个 Channel；<strong>同一个 Channel 的所有 IO 事件和任务都在同一个线程里串行执行</strong>，因此<strong>天然无锁</strong>，这就是<strong>无锁化设计</strong>的来源。</li></ul><p>整个模型可以概括为：<strong>读写分离 + 事件循环 + 任务队列</strong>。</p><p>实践参数：<strong>bossGroup</strong> 一般设 1 个线程（只 accept 够用），<strong>workerGroup</strong> 按 <strong>CPU 核数 × 2</strong> 设置。连接建立后被固定分配到某个 worker EventLoop，之后该连接的所有报文读写、<strong>心跳超时检测</strong>都在同一线程执行，handler 里不用加锁。好处是<strong>线程少、无锁、上下文切换少</strong>。</p><hr><h2 id="_10-netty-的典型应用场景-★★☆" tabindex="-1">10. Netty 的典型应用场景 ★★☆ <a class="header-anchor" href="#_10-netty-的典型应用场景-★★☆" aria-label="Permalink to &quot;10. Netty 的典型应用场景 ★★☆&quot;">​</a></h2><p>Netty 适合<strong>高并发、长连接、自定义协议</strong>的通信场景：</p><ul><li><strong>RPC 框架</strong>底层，如 <strong>Dubbo</strong> 默认用 Netty；</li><li>消息中间件，如 <strong>RocketMQ</strong>；</li><li>分布式协调组件，如 <strong>Zookeeper</strong>；</li><li>API 网关、即时通讯、游戏服务器；</li><li><strong>物联网设备接入</strong>：长连接 + 自定义协议 + 心跳保活。</li></ul><p>不适合的场景是普通<strong>短连接 HTTP 接口</strong>——那是 <strong>Tomcat</strong> 这类 <strong>Servlet 容器</strong>的活，Netty 也能写 HTTP，但没必要。</p><p>判断标准：连接要长期保持、协议要自己定、单机连接数大，才轮到 Netty；一问一答的短连接请求交给 Servlet 容器更省事。</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>BIO</strong> 一个连接一个线程，<strong>NIO</strong> 一个线程多个连接，<strong>Netty</strong> 是 NIO 的<strong>高层封装加优化</strong>。</li><li><strong>Reactor 三模式</strong>：<strong>单线程、多线程、主从多线程</strong>，Netty 默认主从多线程。</li><li><strong>粘包拆包三个解法</strong>：<strong>定长、分隔符、长度字段</strong>，Netty 都有<strong>现成解码器</strong>。</li><li><strong>零拷贝不是不拷贝，是少拷贝</strong>：直接内存、<strong>CompositeByteBuf</strong>、<strong>sendfile</strong>、slice。</li><li>一个 <strong>Channel</strong> 的所有事件都在同一个 <strong>EventLoop 线程</strong>执行，<strong>天然无锁</strong>。</li></ul>',34))])}const f=i(h,[["render",u]]);export{N as __pageData,f as default};
